import { readFileSync, writeFileSync } from 'node:fs';
const g = JSON.parse(readFileSync(process.argv[2], 'utf8'));
let s = `// <auto-generated>
// Golden cases for the traces model: the inputs and the outputs of web/src/components/traces/model.ts (+ the inline
// time-bar code of request.tsx / session.tsx) run on them. Produced by a throwaway esbuild script that imports the real
// TypeScript, not hand-written. Regenerate by re-running that script when the web model changes.
// </auto-generated>
#nullable enable

namespace Astra.Desktop.Tests.Traces;

internal static class TraceGolden
{
    public static readonly (string Name, string Json)[] All =
    [
`;
for (const sc of g) {
  const json = JSON.stringify({ kind: sc.kind, input: sc.input, expected: sc.expected });
  if (json.includes('"""')) throw new Error('triple quote in ' + sc.name);
  s += `        ("${sc.name}", """"""\n${json}\n""""""),\n`;
}
s += `    ];\n}\n`;
writeFileSync(process.argv[3], s);
